import type {ImageSourcePropType} from 'react-native';

import {cardImages, tileImages} from './backgroundList';

/** Background illustrations generated by scripts/make-backgrounds.py (see backgroundList.ts). */
export const tileBackgrounds = tileImages;

const cardBackgrounds: ImageSourcePropType[] = cardImages;

/** v2: the set changed (21 distinct compositions), so every workout picks again. */
export const cardBackgroundsKey = 'card-backgrounds-v2';

export function cardBackground(index: number | undefined): ImageSourcePropType | null {
  return index === undefined || index < 0 ? null : cardBackgrounds[index % cardBackgrounds.length];
}

/**
 * Gives every workout without a background a random one, preferring backgrounds no other
 * workout uses. Returns the same object when nothing changed.
 */
export function assignCardBackgrounds(
  assigned: Record<string, number>,
  workoutIds: string[],
  random: () => number = Math.random,
): Record<string, number> {
  const missing = workoutIds.filter(
    id => assigned[id] === undefined || assigned[id] >= cardBackgrounds.length,
  );
  if (missing.length === 0) {
    return assigned;
  }
  const next = {...assigned};
  for (const id of missing) {
    delete next[id];
    const used = new Set(Object.values(next));
    const free = cardBackgrounds.map((_, index) => index).filter(index => !used.has(index));
    const pool = free.length > 0 ? free : cardBackgrounds.map((_, index) => index);
    next[id] = pool[Math.floor(random() * pool.length)];
  }
  return next;
}

export function parseCardBackgrounds(raw: string | null): Record<string, number> {
  try {
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

/**
 * One background per history session, newest first: derived from the session id (so it stays put)
 * and bumped when it would repeat one of the four cards just above it.
 */
export function sessionBackgroundMap(
  sessions: {id: string; timestamp: number}[],
): Map<string, number> {
  const map = new Map<string, number>();
  const recent: number[] = []; // the last few cards above, to avoid near repeats
  for (const session of [...sessions].sort((a, b) => b.timestamp - a.timestamp)) {
    let hash = 0;
    for (const char of session.id) {
      hash = (hash * 31 + char.charCodeAt(0)) % 2147483647;
    }
    let index = hash % cardBackgrounds.length;
    while (recent.includes(index)) {
      index = (index + 1) % cardBackgrounds.length;
    }
    map.set(session.id, index);
    recent.push(index);
    if (recent.length > 4) {
      recent.shift();
    }
  }
  return map;
}
